 social::CoreSocialService service({identity,address,QString(32,'a'),"global","Private QA"},crypto,socialRpc,output+"/outbox.json");social::NativeDisplayResolver resolver(displayRpc,identity,&owner);social::Services services;services.read=[&](auto request,auto done){service.services().read(request,[&,done](auto snapshot,QString e){if(!e.isEmpty()){done(snapshot,e);return;}resolver.decorate(snapshot,done);});};services.sendChat=service.services().sendChat;ui::SocialView view(output+"/drafts.json",services);view.resize(1366,800);view.setIdentity(identity);view.show();service.changed=[&]{view.refresh();};service.diagnostic=[](QString e){std::cerr<<e.toStdString()<<std::endl;};service.start();
 auto* editor=view.findChild<QPlainTextEdit*>("pgn-social-draft-body-0");auto* send=view.findChild<QPushButton*>("pgn-social-send-0");require(editor&&send,"composer unavailable");const QString message="Private integration check "+QUuid::createUuid().toString(QUuid::WithoutBraces);editor->setPlainText(message);spin([&]{return send->isEnabled();},20000,"signed chat unavailable");send->click();spin([&]{return editor->toPlainText().isEmpty();},15000,"chat was not accepted");
 auto* list=view.findChild<QListWidget*>("pgn-social-list-0");require(list,"message chronology missing");bool named=false;QTimer reader;reader.setInterval(750);QObject::connect(&reader,&QTimer::timeout,&view,[&]{view.refresh();});reader.start();spin([&]{for(int n=0;n<list->count();++n){const auto text=list->item(n)->text();if(text.contains(message)&&text.contains("Social QA operator A"))named=true;}return named;},25000,"fresh signed message with verified author did not render");reader.stop();require(view.grab().save(output+"/named-chat-1366.png"),"chat capture failed");
 QJsonObject counts;for(auto it=methods.begin();it!=methods.end();++it)counts[it.key()]=it.value();QJsonObject result{{"PASS",true},{"signatures",signatures},{"remote_native_signatures",remoteSignatures},{"logical_submissions",logicalSubmissions},{"rpc_submissions",submissions},{"confirmation_in_this_run",false},{"automatic_name",true},{"name",QString("Social QA operator A")},{"chat_name_rendered",named},{"fresh_message",message},{"visible_rows",list->count()},{"rpc_counts",counts},{"scope","Actual product automatic name and consent/verifier/resolver/SocialView/CoreSocialService with real isolated Core25 RPC and remote Native wallet. Component integration test; not an OS click in the frozen application."}};QFile out(output+"/RESULT.json");require(out.open(QIODevice::WriteOnly),"receipt unavailable");out.write(QJsonDocument(result).toJson());std::cout<<QJsonDocument(result).toJson(QJsonDocument::Compact).constData()<<std::endl;service.stop();return 0;
